#!/usr/bin/env bash
# Vuelve a crear los tramos de gameplay del montaje (mismos comandos que engine/mezzanine.py).
# Necesita ffmpeg con libdav1d y zscale. Los tramos se guardan en ./material (1920x1080, 30 fps, H.264 CRF 14).
set -e
mkdir -p material

TONEMAP="zscale=w=1920:h=1080:filter=lanczos:t=linear:npl=100,format=gbrpf32le,zscale=p=bt709,tonemap=tonemap=hable:desat=0,zscale=t=bt709:m=bt709:r=tv,format=yuv420p"
SCALE="scale=1920:1080:flags=lanczos,format=yuv420p"
DECIMATE="mpdecimate=hi=64*12:lo=64*5:frac=0.33,fps=30000/1001"

ffmpeg -n -ss 44.000 -i "https://archive.org/download/youtube-Om4W6tYMF-0/Om4W6tYMF-0.webm" -t 12.000 -an -vf "$SCALE,setpts=N/(30*TB)" -r 30 -fps_mode cfr -c:v libx264 -preset slow -crf 14 -pix_fmt yuv420p -g 30 "material/Om4W6tYMF-0_0044.00_0056.00.mp4"
